app.get('/users/:id', {
  schema: {
    params: z.object({
      id: z.coerce.number().int().positive(),
    }),
    response: {
      200: z.object({
        id: z.number(),
        name: z.string(),
        createdAt: z.date(),
        issuesCount: z.number(),
      }),
      404: z.object({
        error: z.string(),
      }),
    },
  },
}, async (request, reply) => {
  const { id } = request.params

  const [user] = await db
    .select()
    .from(schema.users)
    .where(eq(schema.users.id, id))
    .limit(1)

  if (!user) {
    return reply.status(404).send({ error: 'User not found' })
  }

  // Count user's issues
  const [{ count }] = await db
    .select({ count: sql<number>`count(*)::int` })
    .from(schema.issues)
    .where(eq(schema.issues.userId, id))

  return {
    ...user,
    issuesCount: count,
  }
})

app.get('/health', {
  schema: {
    response: {
      200: z.object({
        status: z.literal('ok'),
        timestamp: z.string(),
        uptime: z.number(),
      }),
    },
  },
}, async () => {
  return {
    status: 'ok' as const,
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
  }
})

// Novo endpoint para tarefas
app.get('/tasks', {
  schema: {
    querystring: z.object({
      page: z.coerce.number().int().positive().default(1),
      limit: z.coerce.number().int().positive().max(100).default(20),
      userId: z.coerce.number().int().positive().optional(),
    }),
    response: {
      200: z.array(z.object({
        content: z.string(),
        status: z.enum(['pending', 'in_progress', 'completed']),
        priority: z.enum(['low', 'medium', 'high']),
        id: z.string(),
      })),
    },
  },
}, async (request, reply) => {
  const { page, limit, userId } = request.query
  const offset = (page - 1) * limit

  const cacheKey = `tasks:${page}:${limit}:${userId || 'all'}`
  const cached = issuesCache.get(cacheKey)

  if (cached && Date.now() - cached.timestamp < CACHE_TTL) {
    reply.header('X-Cache', 'HIT')
    return cached.data
  }

  const conditions = userId ? eq(schema.issues.userId, userId) : undefined

  const issues = await db.select()
    .from(schema.issues)
    .where(conditions)
    .orderBy(desc(schema.issues.createdAt))
    .limit(limit)
    .offset(offset)

  const tasks = issuesToTasks(issues)

  issuesCache.set(cacheKey, { data: tasks, timestamp: Date.now() })
  reply.header('X-Cache', 'MISS')

  return tasks
})

// Rotas de missões removidas - usando missions-routes.ts

// Registrar rotas do Claude
await app.register(claudeRoutes, { prefix: '/api' })

// Registrar rotas de missões
await app.register(missionsRoutes)

// Registrar rotas de limpeza
await app.register(cleanupRoutes)

// Registrar rotas de documentos
await app.register(documentsRoutes)

// Registrar rotas de WebFetch (Hono para Fastify)
await app.register(async function (fastify) {
  // Adaptador simples para Hono -> Fastify
  fastify.all('/api/webfetch/*', async (request, reply) => {
    const path = request.url.replace('/api/webfetch', '')
    const method = request.method

    // Criar request compatível com Hono
    const honoRequest = new Request(`http://localhost${path}`, {
      method: method,
      headers: request.headers as any,
      body: method !== 'GET' && method !== 'HEAD' ? JSON.stringify(request.body) : undefined
    })

    // Executar no Hono
    const honoResponse = await webfetchRoutes.fetch(honoRequest)

    // Retornar resposta
    reply.status(honoResponse.status)
    return honoResponse.json()
  })
}, { prefix: '' })

// Registrar rotas de RAG (Hono para Fastify)
await app.register(async function (fastify) {
  fastify.all('/api/rag/*', async (request, reply) => {
    try {
      const path = request.url.replace('/api/rag', '')
      const method = request.method

      let body = undefined
      if (method !== 'GET' && method !== 'HEAD' && method !== 'DELETE') {
        body = JSON.stringify(request.body)
      }

      const honoRequest = new Request(`http://localhost${path}`, {
        method: method,
        headers: request.headers as any,
        body: body
      })

      const honoResponse = await ragRoutes.fetch(honoRequest)

      reply.status(honoResponse.status)

      // Verifica se a resposta tem conteúdo
      const text = await honoResponse.text()
      if (text) {
        try {
          return JSON.parse(text)
        } catch {
          return { message: text }
        }
      }
      return {}
    } catch (error) {
      console.error('Erro na rota RAG:', error)
      reply.status(500)
      return { error: 'Erro interno no servidor' }
    }
  })
}, { prefix: '' })

// Registrar rotas de sincronização RAG (Hono para Fastify)
await app.register(async function (fastify) {
  fastify.all('/api/rag/sync/*', async (request, reply) => {
    const path = request.url.replace('/api/rag/sync', '')
    const method = request.method

    const honoRequest = new Request(`http://localhost${path}`, {
      method: method,
      headers: request.headers as any,
      body: method !== 'GET' && method !== 'HEAD' ? JSON.stringify(request.body) : undefined
    })

    const honoResponse = await ragSyncRoutes.fetch(honoRequest)

    reply.status(honoResponse.status)
    return honoResponse.json()
  })
}, { prefix: '' })

app.setErrorHandler((error, _request, reply) => {
  app.log.error(error)

  if (error.validation) {
    return reply.status(400).send({
      error: 'Validation Error',
      message: 'Invalid request data',
      details: error.validation,
    })
  }

  if (error.statusCode === 429) {
    return reply.status(429).send({
      error: 'Too Many Requests',
      message: 'Rate limit exceeded. Please try again later.',
    })
  }

  return reply.status(500).send({
    error: 'Internal Server Error',
    message: 'An unexpected error occurred',
  })
})

const start = async () => {
  try {
    await app.listen({ port: 3333, host: '0.0.0.0' })
    app.log.info('🚀 HTTP server running on http://localhost:3333')
  } catch (err) {
    app.log.error(err)
    process.exit(1)
  }
}

start()

import { BrowserRouter, Routes, Route, Link, useLocation } from 'react-router-dom'
import { QueryClient, QueryClientProvider } from '@tanstack/react-query'
import { Toaster } from 'react-hot-toast'
import { ErrorBoundary } from './components/ErrorBoundary'
import { useState, useRef, useEffect } from 'react'

// Importar páginas
import { PotentialIssues } from './pages/PotentialIssues'
import { ClaudeSessions } from './pages/ClaudeSessions'
import Documents from './pages/Documents'
import { ClaudeSessionDetailSimple } from './pages/ClaudeSessionDetailSimple'
import { RAGManagerEnhanced } from './components/RAGManagerEnhanced'

// Criar QueryClient
const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      staleTime: 5 * 60 * 1000,
      retry: false
    }
  }
})

// Componente de Navegação
function Navigation() {
  const location = useLocation()
  const [showDropdown, setShowDropdown] = useState(false)
  const dropdownRef = useRef<HTMLDivElement>(null)

  const isActive = (path: string) => {
    return location.pathname === path
  }

  // Fechar dropdown ao clicar fora
  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setShowDropdown(false)
      }
    }

    document.addEventListener('mousedown', handleClickOutside)
    return () => {
      document.removeEventListener('mousedown', handleClickOutside)
    }
  }, [])

  return (
    <nav className="bg-white shadow-sm mb-6">
      <div className="container mx-auto px-4 py-3">
        <div className="flex space-x-6 flex-wrap items-center">
          {/* Páginas Principais */}
          <Link 
            to="/playbooks" 
            className={`font-medium transition-colors ${
              isActive('/playbooks') || location.pathname.startsWith('/playbooks/') ? 'text-blue-800' : 'text-blue-600 hover:text-blue-800'
            }`}
          >
            Playbooks
          </Link>

          <Link 
            to="/conversas" 
            className={`font-medium transition-colors ${
              isActive('/conversas') ? 'text-blue-800' : 'text-blue-600 hover:text-blue-800'
            }`}
          >
            Conversas
          </Link>

          {/* Separador */}
          <span className="text-gray-300">|</span>

          {/* Páginas do Sistema */}
          <div className="relative" ref={dropdownRef}>
            <button
              onClick={() => setShowDropdown(!showDropdown)}
              className={`font-medium transition-colors flex items-center gap-1 ${
                isActive('/') || isActive('/potential-issues') || isActive('/rag') ? 'text-blue-800' : 'text-blue-600 hover:text-blue-800'
              }`}
            >
              Sistema
              <svg className={`w-4 h-4 transition-transform ${showDropdown ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
              </svg>
            </button>

            {showDropdown && (
              <div className="absolute top-full left-0 mt-2 w-48 bg-white rounded-md shadow-lg border border-gray-200 z-50">
                <Link
                  to="/"
                  onClick={() => setShowDropdown(false)}
                  className={`block px-4 py-2 text-sm hover:bg-gray-100 ${
                    isActive('/') ? 'bg-gray-100 text-blue-800' : 'text-gray-700'
                  }`}
                >
                  Dashboard Principal
                </Link>
                <Link
                  to="/potential-issues"
                  onClick={() => setShowDropdown(false)}
                  className={`block px-4 py-2 text-sm hover:bg-gray-100 ${
                    isActive('/potential-issues') ? 'bg-gray-100 text-blue-800' : 'text-gray-700'
                  }`}
                >
                  Potenciais Problemas
                </Link>
                <Link
                  to="/rag"
                  onClick={() => setShowDropdown(false)}
                  className={`block px-4 py-2 text-sm hover:bg-gray-100 ${
                    isActive('/rag') ? 'bg-gray-100 text-blue-800' : 'text-gray-700'
                  }`}
                >
                  RAG Manager
                </Link>
              </div>
            )}
          </div>
        </div>
      </div>
    </nav>
  )
}

// Dashboard Principal
function Dashboard() {
  return (
    <div className="container mx-auto px-4 py-8">
      <h1 className="text-3xl font-bold mb-6">Sistema de Tarefas Offline-First</h1>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        <div className="bg-white rounded-lg shadow-md p-6">
          <h2 className="text-xl font-semibold mb-4">Funcionalidades Principais</h2>
          <ul className="space-y-3">
            <li className="flex items-center">
              <span className="text-green-600 mr-2">✓</span>
              <span>Playbooks (Sessões Claude)</span>
            </li>
            <li className="flex items-center">
              <span className="text-green-600 mr-2">✓</span>
              <span>Conversas (Documentos)</span>
            </li>
            <li className="flex items-center">
              <span className="text-green-600 mr-2">✓</span>
              <span>Potenciais Problemas</span>
            </li>
            <li className="flex items-center">
              <span className="text-green-600 mr-2">✓</span>
              <span>RAG Manager</span>
            </li>
          </ul>
        </div>

        <div className="bg-white rounded-lg shadow-md p-6">
          <h2 className="text-xl font-semibold mb-4">Características</h2>
          <ul className="space-y-3">
            <li className="flex items-center">
              <span className="text-blue-600 mr-2">🔒</span>
              <span>Offline-First</span>
            </li>
            <li className="flex items-center">
              <span className="text-blue-600 mr-2">🔄</span>
              <span>Sincronização Automática</span>
            </li>
            <li className="flex items-center">
              <span className="text-blue-600 mr-2">🔍</span>
              <span>Busca Semântica</span>
            </li>
            <li className="flex items-center">
              <span className="text-blue-600 mr-2">🤖</span>
              <span>Integração Claude AI</span>
            </li>
          </ul>
        </div>

        <div className="bg-white rounded-lg shadow-md p-6">
          <h2 className="text-xl font-semibold mb-4">Status do Sistema</h2>
          <div className="space-y-3">
            <div className="flex items-center justify-between">
              <span>Backend</span>
              <span className="text-green-600">Online</span>
            </div>
            <div className="flex items-center justify-between">
              <span>Frontend</span>
              <span className="text-green-600">Online</span>
            </div>
            <div className="flex items-center justify-between">
              <span>Banco Local</span>
              <span className="text-green-600">Ativo</span>
            </div>
            <div className="flex items-center justify-between">
              <span>RAG</span>
              <span className="text-green-600">Ativo</span>
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}

// App Principal
function AppContent() {
  return (
    <div className="min-h-screen bg-gray-100">
      <Navigation />

      <Routes>
        {/* Páginas Principais */}
        <Route path="/" element={<Dashboard />} />
        <Route path="/potential-issues" element={<PotentialIssues />} />
        <Route path="/playbooks" element={<ClaudeSessions />} />
        <Route path="/playbooks/:sessionId" element={<ClaudeSessionDetailSimple />} />
        <Route path="/playbooks/:sessionId/:filter" element={<ClaudeSessionDetailSimple />} />
        <Route path="/claude-sessions" element={<ClaudeSessions />} />
        <Route path="/claude-sessions/:sessionId" element={<ClaudeSessionDetailSimple />} />
        <Route path="/claude-sessions/:sessionId/:filter" element={<ClaudeSessionDetailSimple />} />
        <Route path="/documents" element={<Documents />} />
        <Route path="/conversas" element={<Documents />} />
        <Route path="/rag" element={<RAGManagerEnhanced />} />
      </Routes>
    </div>
  )
}

// Componente App com Providers
export function App() {
  return (
    <ErrorBoundary>
      <QueryClientProvider client={queryClient}>
        <BrowserRouter>
          <AppContent />
        </BrowserRouter>
        <Toaster position="top-right" />
      </QueryClientProvider>
    </ErrorBoundary>
  )
}

